class Solution {
public:
    double knightProbability(int n, int k, int row, int column) {
        int dr[8] = {-2, -2, -1, -1, 1, 1, 2, 2};
        int dc[8] = {-1, 1, -2, 2, -2, 2, -1, 1};
        vector<vector<double>> dp(n, vector<double>(n, 0.0));
        vector<vector<double>> next(n, vector<double>(n, 0.0));
        dp[row][column] = 1.0;
        for (int step = 0; step < k; step++) {
            for (int r = 0; r < n; r++)
                for (int c = 0; c < n; c++)
                    next[r][c] = 0.0;
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    if (dp[r][c] == 0.0) continue;
                    double share = dp[r][c] / 8.0;
                    for (int i = 0; i < 8; i++) {
                        int nr = r + dr[i];
                        int nc = c + dc[i];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                            next[nr][nc] += share;
                        }
                    }
                }
            }
            dp.swap(next);
        }
        double total = 0.0;
        for (int r = 0; r < n; r++)
            for (int c = 0; c < n; c++)
                total += dp[r][c];
        return total;
    }
};
